          code: `# Monitor: only one process inside at a time; condition queues
buffer = []
capacity = 2
waiting_producers = []
waiting_consumers = []

def monitor_put(item):
    if len(buffer) == capacity:
        waiting_producers.append(item)
        print(f"Buffer full! Producer waits with {item}")
        return
    buffer.append(item)
    print(f"Put {item} -> buffer: {buffer}")
    if waiting_consumers:
        print("Signal: wake one waiting consumer")

def monitor_get():
    if not buffer:
        waiting_consumers.append("consumer")
        print("Buffer empty! Consumer waits")
        return None
    item = buffer.pop(0)
    print(f"Got {item} -> buffer: {buffer}")
    if waiting_producers:
        item2 = waiting_producers.pop(0)
        buffer.append(item2)
        print(f"Signal: wake producer, put {item2} -> buffer: {buffer}")
    return item

monitor_put("X")
monitor_put("Y")
monitor_put("Z")
monitor_get()
monitor_get()
monitor_get()
print("Final buffer:", buffer)`,
