          code: `# Reference string, 3 frames: FIFO vs LRU page faults
refs = [7, 0, 1, 2, 0, 3, 0, 4, 2, 3, 0, 3, 2]

def fifo(refs, frames):
    memory = []
    faults = 0
    for page in refs:
        if page not in memory:
            faults += 1
            if len(memory) == frames:
                memory.pop(0)
            memory.append(page)
    return faults

def lru(refs, frames):
    memory = []
    faults = 0
    for page in refs:
        if page in memory:
            memory.remove(page)
            memory.append(page)
        else:
            faults += 1
            if len(memory) == frames:
                memory.pop(0)
            memory.append(page)
    return faults

print("Reference string:", refs)
print("FIFO faults (3 frames):", fifo(refs, 3))
print("LRU faults (3 frames):", lru(refs, 3))`,
