      starter: `# SSTF: head at 50, find the service order and total movement
queue = [82, 170, 43, 140, 24, 16, 190]
head = 50

remaining = queue[:]
total = 0
pos = head
order = []
while remaining:
    nearest = min(remaining, key=lambda r: abs(r - pos))
    order.append(nearest)
    total += abs(nearest - pos)
    pos = nearest
    remaining.remove(nearest)

print("SSTF order:", order)
print("Total head movement:", total)`,
